begin;
create temp table collection_ids(key text primary key,id uuid);
insert into collection_ids values('owner','b61f0000-0000-4000-8000-000000000001'),('customer','b61f0000-0000-4000-8000-000000000002'),('other','b61f0000-0000-4000-8000-000000000003');
insert into auth.users(id,email)select id,key||'-collection-fixture@example.invalid'from collection_ids;
create function pg_temp.cid(k text)returns uuid language sql stable as $$select id from pg_temp.collection_ids where key=k$$;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.denied(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got %: %',expected,sqlstate,sqlerrm;end;raise exception 'Denied operation succeeded';end;$$;
do $$begin execute format('grant usage on schema %I to anon,authenticated',pg_my_temp_schema()::regnamespace::text);end;$$;
grant all on collection_ids to authenticated;
grant execute on function pg_temp.cid(text),pg_temp.ok(boolean,text),pg_temp.denied(text,text)to authenticated,anon;
insert into collection_ids select k,gen_random_uuid()from unnest(array['salon','barber','collection','empty','front','side','bad','request'])k;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'))::text,true);
set local role authenticated;
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.cid('salon'),'name','Collection fixture','address','Akurana','opens_at','00:00','closes_at','23:59','weekdays',jsonb_build_array(0,1,2,3,4,5,6)));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.cid('barber'),'salon_id',pg_temp.cid('salon'),'display_name','Collection chair'));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('customer'))::text,true);
select public.customer_collections('create',jsonb_build_object('id',pg_temp.cid('collection'),'title','My next haircut'));
select public.customer_collections('create',jsonb_build_object('id',pg_temp.cid('collection'),'title','Retry'));
select public.customer_collections('create',jsonb_build_object('id',pg_temp.cid('empty'),'title','Empty collection'));
select pg_temp.denied($q$select public.customer_collections('create',jsonb_build_object('title',' '))$q$,'P0001');
select public.customer_collections('add_photos',jsonb_build_object('id',pg_temp.cid('collection'),'photos',jsonb_build_array(jsonb_build_object('id',pg_temp.cid('front'),'title','Front','storage_path',pg_temp.cid('customer')||'/'||pg_temp.cid('front')||'.jpg'),jsonb_build_object('id',pg_temp.cid('side'),'title','Side','storage_path',pg_temp.cid('customer')||'/'||pg_temp.cid('side')||'.jpg'))));
select public.customer_collections('add_photos',jsonb_build_object('id',pg_temp.cid('collection'),'photos',jsonb_build_array(jsonb_build_object('id',pg_temp.cid('front'),'title','Front','storage_path',pg_temp.cid('customer')||'/'||pg_temp.cid('front')||'.jpg'))));
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.customer_collections('list'))c where c->>'id'=pg_temp.cid('collection')::text and jsonb_array_length(c->'photos')=2),'A collection holds both images without retry duplicates');
select pg_temp.denied($q$select public.customer_collections('add_photos',jsonb_build_object('id',pg_temp.cid('collection'),'photos',jsonb_build_array(jsonb_build_object('id',pg_temp.cid('bad'),'storage_path',pg_temp.cid('customer')||'/'||pg_temp.cid('bad')||'.jpg'),jsonb_build_object('storage_path',pg_temp.cid('other')||'/'||gen_random_uuid()||'.jpg'))))$q$,'42501');
select pg_temp.ok(not exists(select 1 from public.customer_haircuts where id=pg_temp.cid('bad')),'An invalid batch rolls back every added photo');
select pg_temp.denied($q$select public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.cid('salon'),'collection_id',pg_temp.cid('empty'),'request_key',gen_random_uuid()))$q$,'P0001');
select pg_temp.ok(not exists(select 1 from public.queue_entries where salon_id=pg_temp.cid('salon')),'An empty collection cannot leave a partial queue entry');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('other'))::text,true);
select pg_temp.ok(jsonb_array_length(public.customer_collections('list'))=0,'Collections are private to their customer');
select pg_temp.denied($q$select public.customer_collections('rename',jsonb_build_object('id',pg_temp.cid('collection'),'title','Stolen'))$q$,'42501');
select pg_temp.denied($q$select public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.cid('salon'),'collection_id',pg_temp.cid('collection'),'request_key',gen_random_uuid()))$q$,'42501');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('customer'))::text,true);
insert into collection_ids select 'queue',(public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.cid('salon'),'barber_id',pg_temp.cid('barber'),'collection_id',pg_temp.cid('collection'),'request_key',pg_temp.cid('request')))->>'id')::uuid;
select public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.cid('salon'),'barber_id',pg_temp.cid('barber'),'collection_id',pg_temp.cid('collection'),'request_key',pg_temp.cid('request')));
insert into collection_ids select 'appointment',(public.customer_command('request_appointment',jsonb_build_object('salon_id',pg_temp.cid('salon'),'barber_id',pg_temp.cid('barber'),'collection_id',pg_temp.cid('collection'),'starts_at',((now()at time zone 'Asia/Colombo')::date+1+'14:00'::time)at time zone 'Asia/Colombo','request_key',gen_random_uuid()))->>'id')::uuid;
select public.customer_collections('rename',jsonb_build_object('id',pg_temp.cid('collection'),'title','Renamed library'));
select public.customer_gallery('rename',jsonb_build_object('id',pg_temp.cid('front'),'title','Changed later'));
select public.customer_collections('remove',jsonb_build_object('id',pg_temp.cid('collection')));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'))::text,true);
select pg_temp.ok((select count(*)=2 from jsonb_array_elements(public.barber_state(pg_temp.cid('barber'))->'styles')r where r->>'collection_title'='My next haircut'and jsonb_array_length(r->'images')=2),'Queue and appointment share every image and the original collection name');
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.barber_state(pg_temp.cid('barber'))->'styles')r,jsonb_array_elements(r->'images')p where p->>'title'='Front'),'Gallery rename/removal cannot rewrite a shared photo snapshot');
select pg_temp.ok(bookmyturn_private.haircut_media_read(pg_temp.cid('customer')||'/'||pg_temp.cid('side')||'.jpg'),'Authorized staff can read the second private photo too');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('other'))::text,true);
select pg_temp.ok(not bookmyturn_private.haircut_media_read(pg_temp.cid('customer')||'/'||pg_temp.cid('side')||'.jpg'),'Unrelated accounts cannot read secondary reference images');
set local role anon;
select pg_temp.denied($q$select public.customer_collections('list')$q$,'42501');
reset role;
select pg_temp.ok((select count(*)=1 from public.queue_entries where salon_id=pg_temp.cid('salon')),'A retried collection join creates only one visit');
select 'PASS: private collection CRUD, atomic multi-photo attachment, immutable visit snapshots, retries and image privacy' result;
rollback;
